#include "hammond/PedalVoice.h"
#include <array>
#include <bit>
#include <cfenv>
#include <cmath>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <limits>

int main() {
    constexpr double eta = std::numeric_limits<double>::denorm_min();
    if (std::fegetround() != FE_TONEAREST) return 2;
    constexpr std::array<std::array<double, 4>, 2> weights{{
        {{0.5, 0.25, 0.125, 0.125}}, {{0.125, 0.5, 0.25, 0.125}}}};
    for (const double sign : {1.0, -1.0}) {
        hammond::PedalBusFrame buses{};
        buses.fill(sign * 0x0.0000000000022p-1022);
        hammond::PedalVoiceFrame actual;
        if (hammond::render_nominal_pedal_voice(buses, {8, 8}, actual) !=
            hammond::Status::Ok) return 3;
        std::cout << "{\"sign\":" << sign << ",\"rows\":[";
        for (std::size_t row = 0; row < weights.size(); ++row) {
            double separate = 0, fused = 0;
            for (const double weight : weights[row]) {
                volatile double product = weight * buses[0];
                separate += product;
                fused = std::fma(weight, buses[0], fused);
            }
            if (row) std::cout << ',';
            std::cout << "{\"separate_eta\":" << separate / eta
                      << ",\"fused_eta\":" << fused / eta
                      << ",\"actual_eta\":" << actual.mixtures[row] / eta
                      << ",\"actual_bits\":"
                      << std::bit_cast<std::uint64_t>(actual.mixtures[row]) << '}';
        }
        std::cout << "],\"actual_output_eta\":" << actual.output / eta << "}\n";
    }
}

